def kthPrimeFraction(arr, k):
    n = len(arr)
    lo, hi = 0.0, 1.0
    while True:
        mid = (lo + hi) / 2
        count = 0
        best_num, best_den = 0, 1
        j = 1
        for i in range(n - 1):
            while j < n and arr[i] > mid * arr[j]:
                j += 1
            if j == n:
                break
            count += n - j
            if arr[i] * best_den > best_num * arr[j]:
                best_num, best_den = arr[i], arr[j]
        if count == k:
            return [best_num, best_den]
        if count < k:
            lo = mid
        else:
            hi = mid
